const axiosModule=require('/Users/tamastyukodi/Development/video-platform-ui/node_modules/axios');
const axios=axiosModule.default;
const mode=new URLSearchParams(window.location.search).get('mode')||'text';
const supported=['text','token','reject'];if(!supported.includes(mode))throw new Error('Unknown fixture mode');
const records=[];let refreshed=false,started=false,refreshFinished=false,checkpoint=false;
const outcomes={profile:'not started',dashboard:'not started',sales:'not started'};
const paths={profile:'api/user/userInfo',dashboard:'api/creator/dashboard/summary',sales:'api/creator/sales/summary'};
function render(){const panel=document.getElementById('qa-refresh-result');if(panel)panel.textContent=JSON.stringify({mode,refreshFinished,transportAuthenticated:refreshed,checkpoint,outcomes,records},null,2);}
function reject401(config){return new axiosModule.AxiosError('Synthetic local401','QA_401',config,null,{status:401,statusText:'Unauthorized',data:{message:'Synthetic local401'},headers:{},config});}
axios.defaults.adapter=async config=>{
 if(config.url==='api/auth/refresh'){
  records.push({method:config.method,url:config.url,status:'pending'});render();
  await new Promise(resolve=>setTimeout(resolve,180));
  refreshFinished=true;
  if(mode==='reject'){records.push({method:config.method,url:config.url,status:401});render();throw reject401(config);}
  refreshed=true;records.push({method:config.method,url:config.url,status:200,response_shape:mode==='text'?'text Refresh successful':'JSON synthetic token'});render();
  return {status:200,statusText:'OK',data:mode==='text'?'Refresh successful':{token:'qa-synthetic-token'},headers:{},config};
 }
 if(!Object.values(paths).includes(config.url))throw new Error('Unregistered request blocked locally');
 const auth=config.headers?.Authorization;
 records.push({method:config.method,url:config.url,status:refreshed?200:401,retry:config._retry===true,authorization_kind:auth===undefined?'absent':auth==='Bearer undefined'?'undefined bearer':'synthetic bearer'});render();
 if(!refreshed)throw reject401(config);
 return {status:200,statusText:'OK',data:{synthetic:true},headers:{},config};
};
window.fetch=async()=>{throw new Error('No network allowed by local refresh harness');};
const http=require('/Users/tamastyukodi/Development/video-platform-ui/src/core/api/http-client.ts').default;
const panel=document.createElement('main');panel.style.cssText='padding:24px;font:16px sans-serif;background:white;color:black';
const heading=document.createElement('h1');heading.textContent='Isolated concurrent refresh test';panel.appendChild(heading);
const description=document.createElement('p');description.textContent='Mode: '+mode+'. Real shared client/interceptor; synthetic local transport. No actual cookies or credentials.';panel.appendChild(description);
const button=document.createElement('button');button.textContent='Run concurrent reads';button.style.cssText='padding:12px';button.onclick=()=>{
 if(started)return;started=true;button.disabled=true;
 for(const [label,url]of Object.entries(paths)){
  outcomes[label]='pending';http.get(url).then(()=>{outcomes[label]='fulfilled';render();},error=>{outcomes[label]='rejected '+(error.response?.status||'guard');render();});
 }
 render();setTimeout(()=>{checkpoint=true;render();},1000);
};panel.appendChild(button);
const output=document.createElement('pre');output.id='qa-refresh-result';output.setAttribute('role','status');panel.appendChild(output);document.body.replaceChildren(panel);render();
